css:
@import url("https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Barlow:wght@400;600;700&display=swap");
:root{--bg:#0C0C0F;--pn:#16161B;--ln:#2A2A32;--or:#FF3D00;--tx:#D9D9E0;--mu:#8E8E9A;--d:"Bebas Neue",Impact,sans-serif;--b:"Barlow",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:18px;line-height:1.6;color:var(--tx);background:var(--bg)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--d);font-weight:400;margin:0;line-height:.95;color:#fff;letter-spacing:.01em}
.wrap{max-width:1240px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--or);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--or);outline-offset:2px}
.hd{position:sticky;top:0;z-index:40;background:rgba(12,12,15,.9);backdrop-filter:blur(10px);border-bottom:1px solid var(--ln)}.nav{display:flex;justify-content:space-between;align-items:center;height:70px}
.logo{font-family:var(--d);font-size:32px;text-decoration:none;color:#fff}.logo span{color:var(--or)}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:600}.menu a{text-decoration:none}.menu a:hover{color:var(--or)}
.btn{display:inline-flex;align-items:center;gap:10px;padding:13px 24px;border-radius:8px;font-weight:700;text-decoration:none;border:0;font-family:var(--b);font-size:16px;cursor:pointer}
.btn-o{background:var(--or);color:#fff}.btn-g{background:var(--pn);color:#fff;border:1px solid var(--ln)}
.burger{display:none;background:none;border:1px solid var(--ln);color:#fff;border-radius:6px;padding:6px 10px;cursor:pointer}
.hero{padding:60px 0}.hg{display:grid;grid-template-columns:1fr 1.2fr;gap:40px;align-items:center}
.hero h1{font-size:clamp(64px,10vw,150px)}.hero h1 span{color:var(--or)}.hero p{font-size:20px;color:var(--mu);max-width:40ch;margin:16px 0 24px}
.reel{position:relative;border-radius:18px;overflow:hidden;aspect-ratio:16/9;border:1px solid var(--ln);cursor:pointer;background:#000}
.reel img{width:100%;height:100%;object-fit:cover;opacity:.75}.play{position:absolute;inset:0;display:grid;place-items:center;border:0;background:none;cursor:pointer}
.play span{width:84px;height:84px;border-radius:50%;background:var(--or);display:grid;place-items:center;box-shadow:0 0 0 12px rgba(255,61,0,.25)}.play span::after{content:"";border-left:24px solid #fff;border-top:15px solid transparent;border-bottom:15px solid transparent;margin-left:6px}
.reel .lbl{position:absolute;left:16px;bottom:14px;font-family:var(--d);font-size:26px;color:#fff}
.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--ln);border-radius:16px;margin-top:40px}
.stats div{padding:22px;border-right:1px solid var(--ln)}.stats div:last-child{border:0}.stats b{font-family:var(--d);font-size:52px;color:#fff;display:block;line-height:1}.stats span{color:var(--mu);font-size:15px}
section{padding:80px 0}.sh{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:24px;flex-wrap:wrap}.sh h2{font-size:clamp(48px,6vw,86px)}
.chips{display:flex;gap:8px;flex-wrap:wrap}.chips button{background:var(--pn);border:1px solid var(--ln);color:var(--mu);border-radius:999px;padding:8px 16px;font:inherit;font-weight:600;cursor:pointer}.chips button[aria-pressed=true]{background:var(--or);border-color:var(--or);color:#fff}
.vids{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.v{background:none;border:0;padding:0;text-align:left;color:inherit;cursor:pointer;font:inherit}
.v .th{position:relative;border-radius:14px;overflow:hidden;aspect-ratio:16/9;background:#000}.v img{width:100%;height:100%;object-fit:cover;transition:transform .4s}.v:hover img{transform:scale(1.05)}
.v .du{position:absolute;right:10px;bottom:10px;background:rgba(0,0,0,.8);color:#fff;font-size:13px;font-weight:700;border-radius:4px;padding:1px 6px}
.v h3{font-family:var(--b);font-weight:700;font-size:18px;margin:10px 0 2px;line-height:1.3}.v small{color:var(--mu)}
.svc{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.sc{background:var(--pn);border:1px solid var(--ln);border-radius:18px;padding:28px}
.sc h3{font-size:40px}.sc .am{font-family:var(--d);font-size:46px;color:var(--or);margin:8px 0}.sc ul{padding-left:18px;margin:0;color:var(--mu)}
.gear{display:flex;gap:10px;flex-wrap:wrap}.gear span{border:1px solid var(--ln);border-radius:8px;padding:8px 14px;background:var(--pn)}
.ct{background:var(--or);border-radius:24px;padding:50px;display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:center;color:#fff}
.ct h2{font-size:clamp(50px,6vw,90px)}.ct p{font-size:19px}.ct form{display:grid;gap:10px}
.ct input,.ct textarea{width:100%;border:0;border-radius:10px;padding:12px 14px;font:inherit;background:#fff;color:#111}.ct .btn{background:#0C0C0F;color:#fff;justify-content:center}
.md{position:fixed;inset:0;background:rgba(0,0,0,.92);z-index:80;display:none;align-items:center;justify-content:center;padding:20px}.md.on{display:flex}
.md .box{width:min(960px,100%);aspect-ratio:16/9;background:#000;border-radius:14px;overflow:hidden;position:relative;display:grid;place-items:center;text-align:center}
.md .box img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.35}.md .box p{position:relative;color:#fff;font-size:18px;max-width:40ch}
.md button{position:absolute;top:16px;right:16px;background:none;border:0;color:#fff;font-size:36px;cursor:pointer}
footer{border-top:1px solid var(--ln);padding:28px 0;color:var(--mu);font-size:15px}.ft{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
@media(max-width:900px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:70px;left:0;right:0;background:var(--bg);padding:20px;gap:14px;border-bottom:1px solid var(--ln)}
.hg,.ct{grid-template-columns:1fr}.vids,.svc{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr 1fr}.stats div:nth-child(2){border-right:0}.ct{padding:30px}}
@media(max-width:560px){.vids,.svc{grid-template-columns:1fr}}

javascript:
const V=[["How I edit a 20-minute video in 3 hours","YouTube","18:24","1.2M views","1574717024653-61fd2cf4d44d"],["Mountain brand film for Summit Tours","Brand","1:30","Client project","1492691527719-9d1e07e534b4"],["5 cuts every beginner should learn","Shorts","0:58","3.4M views","1516321318423-f06f85e504b3"],["Colour grading a travel vlog","YouTube","14:02","640K views","1506905925346-21bda4d32df4"],["Headphones launch ad","Brand","0:45","Client project","1583394838336-acd977736f90"],["Sound design in 60 seconds","Shorts","0:59","2.1M views","1470071459604-3b5ec3a7fe05"]];
const $=id=>document.getElementById(id);
function vids(c){$('vids').innerHTML=V.filter(v=>c==='all'||v[1]===c).map(v=>`<button class="v" type="button" data-v="${v[0]}" data-i="${v[4]}"><div class="th"><img src="https://images.unsplash.com/photo-${v[4]}?w=640&h=360&q=75&auto=format&fit=crop" alt="" width="640" height="360" loading="lazy"><span class="du">${v[2]}</span></div><h3>${v[0]}</h3><small>${v[1]} · ${v[3]}</small></button>`).join('')}
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));vids(b.dataset.c)};vids('all');
function open(t,i){$('mt').textContent='"'+t+'" would play here. Paste your YouTube or Vimeo embed code into this box.';$('mi').src=`https://images.unsplash.com/photo-${i}?w=1200&q=70&auto=format&fit=crop`;$('md').classList.add('on');$('mx').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v]');if(b&&b.tagName==='BUTTON')open(b.dataset.v,b.dataset.i||'1574717024653-61fd2cf4d44d')});
$('mx').onclick=()=>$('md').classList.remove('on');document.addEventListener('keydown',e=>{if(e.key==='Escape')$('md').classList.remove('on')});
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
